const editor=document.getElementById('editor'),tabsEl=document.getElementById('tabs');
let tabs=[{id:1,name:'Untitled.txt',filename:null,content:''}],activeId=1,nextId=2;

function currentTab(){return tabs.find(t=>t.id===activeId)}
function persistActive(){const t=currentTab();if(t)t.content=editor.innerHTML}
function renderTabs(){
  tabsEl.innerHTML='';
  tabs.forEach(t=>{
    const el=document.createElement('div');
    el.className='tab'+(t.id===activeId?' active':'');
    el.innerHTML='<span>'+t.name+'</span>';
    el.onclick=()=>switchTab(t.id);
    const x=document.createElement('button');x.textContent='✕';
    x.onclick=(e)=>{e.stopPropagation();closeTab(t.id)};
    el.appendChild(x);tabsEl.appendChild(el);
  });
}
function switchTab(id){persistActive();activeId=id;editor.innerHTML=currentTab().content;renderTabs();editor.focus()}
function newTab(){persistActive();const t={id:nextId++,name:'Untitled.txt',filename:null,content:''};tabs.push(t);switchTab(t.id)}
function closeTab(id){
  const i=tabs.findIndex(t=>t.id===id);if(i<0)return;
  tabs.splice(i,1);
  if(tabs.length===0){tabs.push({id:nextId++,name:'Untitled.txt',filename:null,content:''})}
  if(id===activeId){activeId=tabs[Math.max(0,i-1)].id;editor.innerHTML=currentTab().content}
  renderTabs();
}
document.getElementById('tabAdd').onclick=newTab;
renderTabs();

// Menus
document.querySelectorAll('.menu-btn').forEach(btn=>{
  btn.onclick=(e)=>{
    e.stopPropagation();
    const list=document.getElementById('menu'+btn.dataset.menu[0].toUpperCase()+btn.dataset.menu.slice(1));
    const wasOpen=list.classList.contains('open');
    document.querySelectorAll('.menu-list').forEach(m=>m.classList.remove('open'));
    document.querySelectorAll('.menu-btn').forEach(b=>b.classList.remove('open'));
    if(!wasOpen){list.classList.add('open');btn.classList.add('open')}
  };
});
document.addEventListener('click',()=>{document.querySelectorAll('.menu-list').forEach(m=>m.classList.remove('open'));document.querySelectorAll('.menu-btn').forEach(b=>b.classList.remove('open'))});

function showStatus(msg){document.getElementById('statusMsg').textContent=msg;setTimeout(()=>document.getElementById('statusMsg').textContent='Ready',2500)}

// File open
document.getElementById('menuFile').addEventListener('click',e=>{
  const cmd=e.target.closest('button')?.dataset.cmd;if(!cmd)return;
  if(cmd==='new')newTab();
  else if(cmd==='open')document.getElementById('fileOpenInput').click();
  else if(cmd==='save')doSave(false);
  else if(cmd==='saveas')doSave(true);
  else if(cmd==='image')document.getElementById('imageInput').click();
});
document.getElementById('fileOpenInput').onchange=(e)=>{
  const f=e.target.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{
    persistActive();
    const empty=currentTab().content==='';
    const t=empty?currentTab():{id:nextId++,name:f.name,filename:f.name,content:''};
    if(!empty)tabs.push(t);
    t.name=f.name;t.filename=f.name;
    activeId=t.id;editor.textContent=r.result;t.content=editor.innerHTML;
    renderTabs();showStatus('Opened '+f.name);
  };
  r.readAsText(f);e.target.value='';
};

// Insert image
document.getElementById('imageInput').onchange=(e)=>{
  const f=e.target.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{editor.focus();document.execCommand('insertImage',false,r.result)};
  r.readAsDataURL(f);e.target.value='';
};

// Save — works in the Electron wrapper or as a plain local file
async function getSaver(){
  if(window.claude){try{return {type:'claude',api:await window.claude.use('downloads')}}catch(e){}}
  if(window.electronAPI)return {type:'electron',api:window.electronAPI};
  return {type:'browser'};
}
async function doSave(forcePrompt){
  const t=currentTab();
  const text=editor.innerText;
  const suggested=t.filename||t.name||'Untitled.txt';
  const saver=await getSaver();
  try{
    if(saver.type==='electron'){
      // Electron does not implement window.prompt() (by design, it silently
      // does nothing) — the native Save dialog below handles both the file
      // name AND the destination folder, exactly like a normal desktop app.
      if(!forcePrompt&&t.fullPath){
        const direct=await saver.api.saveFileDirect(t.fullPath,text);
        if(direct&&direct.ok){showStatus('Saved: '+t.fullPath);return}
        // fall through to the dialog if the direct write failed for any reason
      }
      const res=await saver.api.saveFile(suggested,text);
      if(res&&res.canceled)return;
      t.fullPath=res.filePath;
      t.filename=res.filePath?res.filePath.split(/[\\/]/).pop():suggested;
      t.name=t.filename;renderTabs();
      showStatus('Saved: '+(res.filePath||t.filename));
      return;
    }
    let name=t.filename&&!forcePrompt?t.filename:window.prompt('Save as file name:',suggested);
    if(!name)return;
    if(!/\.txt$/i.test(name))name+='.txt';
    if(saver.type==='claude'){
      const res=await saver.api.save({filename:name,data:text});
      showStatus(res.status==='saved'?'Saved: '+name:'File sent');
    }else{
      const blob=new Blob([text],{type:'text/plain'});
      const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();
      showStatus('Saved: '+name);
    }
    t.filename=name;t.name=name;renderTabs();
  }catch(err){
    if(err&&err.code==='declined')return;
    showStatus('Save failed: '+(err&&(err.message||err.code)||''));
  }
}

// View / zoom
const zoomSlider=document.getElementById('zoomSlider'),zoomValueLabel=document.getElementById('zoomValueLabel');
function setZoom(val){
  val=Math.max(25,Math.min(300,Math.round(val)));
  document.querySelector('.editor-wrap').style.zoom=(val/100);
  document.getElementById('zoomLabel').textContent=val+'%';
  zoomValueLabel.textContent=val+'%';
  zoomSlider.value=val;
  save('zoom',val);
}
zoomSlider.oninput=()=>setZoom(zoomSlider.value);
document.getElementById('zoomIn').onclick=()=>setZoom(+zoomSlider.value+10);
document.getElementById('zoomOut').onclick=()=>setZoom(+zoomSlider.value-10);
document.getElementById('menuView').addEventListener('click',e=>{
  const z=e.target.closest('button')?.dataset.zoom;if(!z)return;setZoom(+z);
});
document.querySelector('.editor-wrap').addEventListener('wheel',(e)=>{
  if(!(e.ctrlKey||e.metaKey))return;
  e.preventDefault();setZoom(+zoomSlider.value+(e.deltaY<0?5:-5));
},{passive:false});

document.getElementById('menuSettings').addEventListener('click',e=>{
  if(e.target.closest('button')?.dataset.cmd==='opensettings')openSettings();
});

// Formatting
document.getElementById('fontFamily').onchange=function(){editor.focus();document.execCommand('fontName',false,this.value)};
document.getElementById('fontSize').onchange=function(){
  editor.focus();document.execCommand('fontSize',false,'7');
  editor.querySelectorAll('font[size="7"]').forEach(f=>{f.removeAttribute('size');f.style.fontSize=this.value+'px'});
};
document.getElementById('blockStyle').onchange=function(){editor.focus();document.execCommand('formatBlock',false,this.value)};
document.querySelectorAll('.toolbar button[data-cmd]').forEach(b=>{
  b.onclick=()=>{editor.focus();b.dataset.cmd==='image'?document.getElementById('imageInput').click():document.execCommand(b.dataset.cmd);updateToolbarState()};
});
// Toolbar reflects the current selection, like a real word processor
function updateToolbarState(){
  ['bold','italic','underline','justifyLeft','justifyCenter','justifyRight','insertUnorderedList','insertOrderedList'].forEach(cmd=>{
    const btn=document.querySelector('.toolbar button[data-cmd="'+cmd+'"]');
    if(!btn)return;
    try{btn.classList.toggle('active',document.queryCommandState(cmd))}catch(e){}
  });
}
document.addEventListener('selectionchange',()=>{
  const sel=document.getSelection();
  if(sel&&sel.anchorNode&&editor.contains(sel.anchorNode))updateToolbarState();
});
editor.addEventListener('keyup',updateToolbarState);
editor.addEventListener('mouseup',updateToolbarState);

// Settings panel
const settingsPanel=document.getElementById('settingsPanel'),overlay=document.getElementById('overlay');
function openSettings(){settingsPanel.classList.add('open');overlay.classList.add('open')}
function closeSettings(){settingsPanel.classList.remove('open');overlay.classList.remove('open')}
document.getElementById('settingsBtn').onclick=openSettings;
document.getElementById('spClose').onclick=closeSettings;
overlay.onclick=closeSettings;

// Native window controls: only shown when running inside the Electron wrapper,
// which now owns the ONLY title bar (the OS's own one is turned off in main.js).
if(window.electronAPI&&window.electronAPI.isElectron){
  document.getElementById('winControls').classList.add('show');
  document.getElementById('winMinBtn').onclick=()=>window.electronAPI.minimizeWindow();
  document.getElementById('winMaxBtn').onclick=()=>window.electronAPI.maximizeWindow();
  document.getElementById('winCloseBtn').onclick=()=>window.electronAPI.closeWindow();
}

// Theme: any color, not just dark/light. Dark/Light buttons are quick presets
// that feed the same custom-color system, and the header can opt out of following it.
function hexToRgb(hex){const h=hex.replace('#','');return {r:parseInt(h.substr(0,2),16),g:parseInt(h.substr(2,2),16),b:parseInt(h.substr(4,2),16)}}
function toHex(v){return Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')}
function mix(hex,target,amt){const c=hexToRgb(hex);return '#'+toHex(c.r+(target[0]-c.r)*amt)+toHex(c.g+(target[1]-c.g)*amt)+toHex(c.b+(target[2]-c.b)*amt)}
function relLuminance({r,g,b}){const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)}
function applyThemeColor(hex,persist=true){
  const isDark=relLuminance(hexToRgb(hex))<0.5;
  const text=isDark?'#eef1f6':'#1b1e24';
  const muted=isDark?'rgba(238,241,246,.58)':'rgba(27,30,36,.58)';
  const toward=isDark?[255,255,255]:[0,0,0];
  const root=document.documentElement.style;
  root.setProperty('--bg',hex);
  root.setProperty('--panel',mix(hex,toward,isDark?0.09:0.045));
  root.setProperty('--panel2',mix(hex,toward,isDark?0.16:0.09));
  root.setProperty('--border',mix(hex,toward,isDark?0.26:0.16));
  root.setProperty('--text',text);
  root.setProperty('--muted',muted);
  document.getElementById('themeColorMeta').content=hex;
  document.getElementById('themeColorPicker').value=hex;
  document.querySelectorAll('.seg [data-theme]').forEach(b=>{
    const preset=b.dataset.theme==='dark'?'#0a0e17':'#eef0f3';
    b.classList.toggle('active',preset.toLowerCase()===hex.toLowerCase());
  });
  if(persist)save('themeColor',hex);
}
document.getElementById('themeColorPicker').oninput=function(){applyThemeColor(this.value)};
document.querySelectorAll('.seg [data-theme]').forEach(b=>b.onclick=()=>applyThemeColor(b.dataset.theme==='dark'?'#0a0e17':'#eef0f3'));

// Header (title bar) color: independent from the main theme, with a "follow main theme" option.
function applyHeaderColor(){
  const follow=document.getElementById('headerFollowTheme').checked;
  const picker=document.getElementById('headerColorPicker');
  picker.disabled=follow;
  document.querySelector('.titlebar').style.background=follow?'':picker.value;
  save('headerFollow',follow?'1':'0');
  if(!follow)save('headerColor',picker.value);
}
document.getElementById('headerFollowTheme').onchange=applyHeaderColor;
document.getElementById('headerColorPicker').oninput=applyHeaderColor;

function applyEditorTint(){
  const col=document.getElementById('bgColor').value,op=document.getElementById('bgOpacity').value;
  const r=parseInt(col.slice(1,3),16),g=parseInt(col.slice(3,5),16),bl=parseInt(col.slice(5,7),16);
  editor.style.background='rgba('+r+','+g+','+bl+','+(op/100)+')';
  document.getElementById('opacityVal').textContent=op;
  save('bgColor',col);save('bgOpacity',op);
}
document.getElementById('bgColor').oninput=applyEditorTint;
document.getElementById('bgOpacity').oninput=applyEditorTint;

// Wallpaper: resize before storing so larger images remain reliable in local storage.
function setWallpaper(dataUrl, persist=true){
  const layer=document.getElementById('wallpaperLayer');
  if(dataUrl){
    layer.style.backgroundImage='url("'+dataUrl.replace(/"/g,'\"')+'")';
  }else{
    layer.style.backgroundImage='none';
  }
  if(persist)save('wallpaper',dataUrl||'');
}
function prepareWallpaper(file, callback){
  const r=new FileReader();
  r.onload=()=>{
    const img=new Image();
    img.onload=()=>{
      const max=2400;
      const scale=Math.min(1,max/img.width,max/img.height);
      const w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));
      const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
      const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,w,h);
      callback(canvas.toDataURL('image/jpeg',0.82));
    };
    img.onerror=()=>showStatus('Could not load wallpaper');
    img.src=r.result;
  };
  r.readAsDataURL(file);
}
document.getElementById('wallpaperInput').onchange=(e)=>{
  const f=e.target.files[0];if(!f)return;
  prepareWallpaper(f,data=>{setWallpaper(data,true);showStatus('Wallpaper updated')});
  e.target.value='';
};
document.getElementById('wallpaperClear').onclick=()=>{setWallpaper('',true);showStatus('Wallpaper removed')};

// Tab icon: this is only the icon shown inside the app beside the tabs. It does not control the Windows app icon.
const DEFAULT_APP_ICON='data:image/png;base64,';
const appLogoButton=document.getElementById('appLogoButton');
const appLogoImage=document.getElementById('appLogoImage');
const appIconInput=document.getElementById('appIconInput');
const iconPreview=document.getElementById('iconPreview');
const iconPreviewImage=document.getElementById('iconPreview').querySelector('img');
function setAppIcon(dataUrl,persist=true){
  const has=!!dataUrl;
  appLogoImage.src=has?dataUrl:'';
  appLogoButton.classList.toggle('has-icon',has);
  iconPreviewImage.src=has?dataUrl:'';
  iconPreview.classList.toggle('has-icon',has);
  if(persist)save('appIcon',dataUrl||'');
}
appLogoButton.onclick=()=>appIconInput.click();
document.getElementById('chooseIconButton').onclick=()=>appIconInput.click();
document.getElementById('clearIconButton').onclick=()=>{setAppIcon('',true);showStatus('Tab icon removed')};
appIconInput.onchange=(e)=>{
  const f=e.target.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{setAppIcon(r.result,true);showStatus('Tab icon updated')};
  r.readAsDataURL(f);e.target.value='';
};

// Local persistence of settings only (per-device, private to this viewer)
function save(k,v){try{localStorage.setItem('openpad_'+k,v)}catch(e){}}
function load(k){try{return localStorage.getItem('openpad_'+k)}catch(e){return null}}
function setupInstallable(){
  const icon=load('appIcon')||DEFAULT_APP_ICON; // desktop/PWA icon matches the in-app icon by default
  document.getElementById('appleIcon').href=icon;
  const manifest={name:'Diary Note — Free Notepad',short_name:'Diary Note',description:'A simple text editor anyone can use.',start_url:'.',display:'standalone',background_color:'#0a0e17',theme_color:'#0a0e17',icons:[{src:icon,sizes:'256x256',type:'image/png'}]};
  const blob=new Blob([JSON.stringify(manifest)],{type:'application/manifest+json'});
  document.getElementById('manifestLink').href=URL.createObjectURL(blob);
}
(function init(){
  const themeColor=load('themeColor')||'#0a0e17';applyThemeColor(themeColor,false);
  const hf=load('headerFollow');document.getElementById('headerFollowTheme').checked=(hf===null)?true:hf==='1';
  const hc=load('headerColor');if(hc)document.getElementById('headerColorPicker').value=hc;
  applyHeaderColor();
  const wp=load('wallpaper');if(wp)setWallpaper(wp,false);
  const bc=load('bgColor');if(bc)document.getElementById('bgColor').value=bc;
  const bo=load('bgOpacity');if(bo!==null)document.getElementById('bgOpacity').value=bo;
  applyEditorTint();
  const savedIcon=load('appIcon');setAppIcon(savedIcon||DEFAULT_APP_ICON,false); // same image as the desktop icon until changed
  const z=load('zoom');if(z)setZoom(+z);
  setupInstallable();
})();

// Keyboard shortcuts
document.addEventListener('keydown',(e)=>{
  if(!(e.ctrlKey||e.metaKey))return;
  const k=e.key.toLowerCase();
  if(k==='n'){e.preventDefault();newTab()}
  else if(k==='o'){e.preventDefault();document.getElementById('fileOpenInput').click()}
  else if(k==='s'&&e.shiftKey){e.preventDefault();doSave(true)}
  else if(k==='s'){e.preventDefault();doSave(false)}
  else if(k==='='||k==='+'){e.preventDefault();setZoom(+zoomSlider.value+10)}
  else if(k==='-'){e.preventDefault();setZoom(+zoomSlider.value-10)}
  else if(k==='0'){e.preventDefault();setZoom(100)}
});
